const helpers=runtimeHelpers.toString().replace(/^function runtimeHelpers\(\)\{\n?/,'').replace(/\n?\}$/,'');
const p=(id,type,required=false,extra={})=>({id,name:id.replace(/([A-Z])/g,' $1').replace(/^./,s=>s.toUpperCase()),type,...(type.startsWith('@')?{typeVersion:1}:{}),...(required?{required:true}:{}),...extra});
