 const types=[['ga4.dateRange','ga4','GA4 Date Range','dateRange'],['ga4.dateRanges','ga4','GA4 Date Ranges','dateRanges'],['ga4.dimension','ga4','GA4 Dimension','dimension'],['ga4.dimensions','ga4','GA4 Dimensions','dimensions'],['ga4.metric','ga4','GA4 Metric','metric'],['ga4.metrics','ga4','GA4 Metrics','metrics'],['ga4.filter','ga4','GA4 Filter Expression','filter'],['ga4.order','ga4','GA4 Order By List','order'],['ga4.request','ga4','GA4 Report Request','reportRequest'],['ga4.response','ga4','GA4 Report Response','reportResponse'],['ga4.row','ga4','GA4 Named Row','namedRow'],['ga4.rows','ga4','GA4 Named Rows','namedRows'],['ga4.result','ga4','GA4 Paged Report Result','reportResult'],['ga4.metadata','ga4','GA4 Metadata','metadata'],['ga4.compatibility','ga4','GA4 Compatibility Result','compatibility'],['ga4.realtimeRequest','ga4','GA4 Realtime Request','realtimeRequest'],['ads.query','ads','Google Ads Search Request','adsQuery'],['ads.row','ads','Google Ads Row','adsRow'],['ads.rows','ads','Google Ads Rows','adsRows'],['ads.page','ads','Google Ads Search Page','adsPage'],['ads.result','ads','Google Ads Paged Result','adsResult'],['ads.customers','ads','Google Ads Accessible Customers','adsCustomers'],['ads.campaignSummary','ads','Google Ads Campaign Summary','adsCampaignSummary'],['ads.campaignSummaries','ads','Google Ads Campaign Summaries','adsCampaignSummaries']];
 for(const[key,family,name,schemaKey]of types)add(key,family,name,[],[],'',`Typed reusable ${name.toLowerCase()} contract. Schema is self-contained; provider remainders are explicitly retained where permitted.`,conf(),'type',S[schemaKey]);

